   860|async function generateUniqueDealTitle(title: string, projectName: string, existingId: string | undefined, useSupabase: boolean): Promise<{ title: string; projectName: string }> {
   861|  if (!title && !projectName) return { title, projectName };
   862|
   863|  const baseName = (title || projectName || '').trim();
   864|  if (!baseName) return { title, projectName };
   865|
   866|  try {
   867|    let existingNames: string[] = [];
   868|
   869|    if (useSupabase) {
   870|      const { data } = await supabase
   871|        .from('jv_deals')
   872|        .select('id, title, project_name')
   873|        .not('status', 'in', '("trashed","permanently_deleted","deleted")');
   874|      if (data && Array.isArray(data)) {
   875|        existingNames = data
   876|          .filter((d: any) => !existingId || d.id !== existingId)
   877|          .map((d: any) => ((d.title || d.project_name || '') as string).trim().toUpperCase());
   878|      }
   879|    }
   880|
   881|    const localDeals = await getLocalDeals();
   882|    const localNames = localDeals
   883|      .filter(d => !isDeletedOrTrashed(d) && (!existingId || d.id !== existingId))
   884|      .map(d => ((d.title || d.projectName || d.project_name || '') as string).trim().toUpperCase());
   885|
   886|    const allNames = new Set([...existingNames, ...localNames]);
   887|
   888|    const upperBase = baseName.toUpperCase();
   889|    if (!allNames.has(upperBase)) {
   890|      console.log('[JV-Storage] Deal name is unique:', baseName);
   891|      return { title, projectName };
   892|    }
   893|
   894|    const baseWithoutNum = baseName.replace(/\s+\d+$/, '').trim();
   895|    const upperBaseNoNum = baseWithoutNum.toUpperCase();
   896|
   897|    let maxNum = 0;
   898|    for (const name of allNames) {
   899|      if (name === upperBaseNoNum) {
   900|        maxNum = Math.max(maxNum, 1);
   901|      }
   902|      const match = name.match(new RegExp(`^${upperBaseNoNum.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s+(\\d+)$`));
   903|      if (match) {
   904|        maxNum = Math.max(maxNum, parseInt(match[1] ?? '0', 10));
   905|      }
   906|    }
   907|
   908|    const nextNum = maxNum + 1;
   909|    const uniqueName = `${baseWithoutNum} ${nextNum}`;
   910|    console.log('[JV-Storage] Duplicate name detected! "' + baseName + '" → "' + uniqueName + '"');
   911|
   912|    return {
   913|      title: title ? uniqueName : title,
   914|      projectName: projectName ? uniqueName : projectName,
   915|    };
   916|  } catch (err) {
   917|    console.log('[JV-Storage] generateUniqueDealTitle error (non-critical):', (err as Error)?.message);
   918|    return { title, projectName };
   919|  }
   920|}
